<div class="page-heading"><div><p class="eyebrow">CATATAN KAFE</p><h1>Riwayat pesanan</h1><p class="page-subtitle">Pesanan terbaru beserta status dan detail pembayarannya.</p></div><a class="button button-primary" href="<?=e(url('transaction'))?>">＋ <span>Pesanan baru</span></a></div><section class="panel"><div class="panel-head"><div><h2>Semua transaksi</h2><p>100 pesanan terakhir</p></div></div><div class="table-scroll"><table><thead><tr><th>No. faktur</th><th>Tanggal & jam</th><th>Kasir</th><th>Jenis</th><th>Pembayaran</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($data['orders'] as $o):?><tr><td class="invoice-cell"><?=e($o['invoice_number'])?></td><td><?=e(date('d/m/Y H:i',strtotime($o['created_at'])))?></td><td><?=e($o['cashier'])?></td><td><?=$o['order_type']==='dine_in'?'Dine in · Meja '.e($o['table_number']):'Takeaway'?></td><td><?=e(payment_label($o['payment_method']))?></td><td class="money-cell"><?=rupiah($o['grand_total'])?></td><td><span class="status status-<?=e($o['status'])?>"><?=e(status_label($o['status']))?></span></td><td><div class="table-actions"><a class="row-link" href="<?=e(url('receipt',['id'=>$o['id']]))?>">Struk</a><?php if($o['status']!=='cancelled'):?><form method="post" class="status-form"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" aria-label="Ubah status pesanan" data-status-confirm data-current-status="<?=e($o['status'])?>"><option value="processing" <?=$o['status']==='processing'?'selected':''?>>Diproses</option><option value="completed" <?=$o['status']==='completed'?'selected':''?>>Selesai</option><option value="cancelled">Batalkan</option></select></form><?php endif?></div></td></tr><?php endforeach;if(!$data['orders']):?><tr><td colspan="8" class="table-empty">Belum ada transaksi yang tercatat.</td></tr><?php endif?></tbody></table></div></section>
<dialog class="status-dialog" id="statusDialog" aria-labelledby="statusDialogTitle"><div class="status-dialog-mark" id="statusDialogMark" aria-hidden="true">✓</div><h2 id="statusDialogTitle">Perbarui status pesanan?</h2><p id="statusDialogMessage">Status pesanan akan diperbarui.</p><div class="status-dialog-actions"><button type="button" class="button button-quiet" id="cancelStatusChange">Kembali</button><button type="button" class="button button-primary" id="confirmStatusChange">Konfirmasi</button></div></dialog>
